// - Near silence at start (0.0 – 0.6s)
// - Quick handwriting friction during "Rohan" (0.60s – 1.40s)
// - Real silence during pen lift (1.40s – 1.58s)
// - Quick handwriting friction during "Rakshe" (1.58s – 2.48s)
// - Deliberate quiet flourish pause (2.48s – 2.65s)
// - Satisfying decisive underline flourish sweep (2.65s – 3.10s)
// - Settle silence & spatial dissolving transition into 3D world
// - Browser autoplay handling & unobtrusive sound pill controls
// ────────────────────────────────────────────────────────────────────
class PenAudio {
  constructor() {
    this.audioEl       = null;
    this.ctx           = null;
    this.sourceNode    = null;
    this.gainNode      = null;
    this.filterNode    = null;
    this.muted         = false;
    this.unlocked      = false;
    this.isBlocked     = true;
    this.onStateChange = null;
    this._baseVolume   = 0.85;
    this._isSetup      = false;
  }

  async setup(onStateChange) {
    this.onStateChange = onStateChange || (() => {});

    this.audioEl = new Audio();
    this.audioEl.preload = 'auto';
    this.audioEl.volume = this._baseVolume;

    const canWebm = this.audioEl.canPlayType('audio/webm; codecs="opus"');
    const canMp3  = this.audioEl.canPlayType('audio/mpeg');

    const base = import.meta.env.BASE_URL || './';
    const cleanBase = base.endsWith('/') ? base : base + '/';

    if (canMp3) {
      this.audioEl.src = `${cleanBase}signature-pen.mp3`;
    } else if (canWebm) {
      this.audioEl.src = `${cleanBase}signature-pen.webm`;
    } else {
      this.audioEl.src = `${cleanBase}signature-pen.wav`;
    }

    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (AudioCtx) {
        this.ctx = new AudioCtx();
        this.gainNode = this.ctx.createGain();
        this.gainNode.gain.value = this._baseVolume;

        // Warm acoustic filter: lowpass at 4200 Hz eliminates digital harshness
        this.filterNode = this.ctx.createBiquadFilter();
        this.filterNode.type = 'lowpass';
        this.filterNode.frequency.value = 4200;
        this.filterNode.Q.value = 0.7;

        this.sourceNode = this.ctx.createMediaElementSource(this.audioEl);
        this.sourceNode.connect(this.filterNode);
        this.filterNode.connect(this.gainNode);
        this.gainNode.connect(this.ctx.destination);

        if (this.ctx.state === 'running') {
          this.isBlocked = false;
          this.unlocked = true;
          this.onStateChange('active');
          this._isSetup = true;
          return;
        }
      }
    } catch (_) {
      // Fallback to HTMLAudioElement directly
    }

    this.isBlocked = true;
    this.onStateChange('blocked');
    this._isSetup = true;
  }

  async unlock() {
    this.unlocked = true;
    this.isBlocked = false;

    if (this.ctx && this.ctx.state === 'suspended') {
      try {
        await this.ctx.resume();
      } catch (_) {}
    }

    this.onStateChange(this.muted ? 'muted' : 'active');
  }

  playAt(timeInSeconds = 0) {
    if (this.muted || !this.audioEl) return;

    try {
      if (this.ctx && this.ctx.state === 'suspended') {
        this.ctx.resume().catch(() => {});
      }

      this.audioEl.currentTime = Math.max(0, timeInSeconds);
      const p = this.audioEl.play();
      if (p && p.catch) {
        p.then(() => {
          this.isBlocked = false;
          this.onStateChange(this.muted ? 'muted' : 'active');
        }).catch(() => {
          this.isBlocked = true;
          this.onStateChange('blocked');
        });
      }
    } catch (_) {
      this.isBlocked = true;
      this.onStateChange('blocked');
    }
  }

  fadeOut(duration = 0.45) {
    if (!this.audioEl) return;

    if (this.ctx && this.gainNode && this.filterNode) {
      try {
        const now = this.ctx.currentTime;
        this.gainNode.gain.cancelScheduledValues(now);
        this.gainNode.gain.setValueAtTime(this.gainNode.gain.value, now);
        this.gainNode.gain.linearRampToValueAtTime(0.0001, now + duration);

        this.filterNode.frequency.cancelScheduledValues(now);
        this.filterNode.frequency.setValueAtTime(this.filterNode.frequency.value, now);
        this.filterNode.frequency.exponentialRampToValueAtTime(180, now + duration);

        setTimeout(() => this.stop(), duration * 1000 + 50);
        return;
      } catch (_) {}
    }

    const startVol = this.audioEl.volume;
    const startTime = performance.now();
    const tick = () => {
      const elapsed = (performance.now() - startTime) / (duration * 1000);
      if (elapsed >= 1) {
        this.stop();
        if (this.audioEl) this.audioEl.volume = startVol;
      } else {
        if (this.audioEl) this.audioEl.volume = startVol * (1 - elapsed);
        requestAnimationFrame(tick);
      }
    };
    requestAnimationFrame(tick);
  }

  toggleMute() {
    this.muted = !this.muted;

    if (this.gainNode && this.ctx) {
      try {
        this.gainNode.gain.setValueAtTime(this.muted ? 0.0001 : this._baseVolume, this.ctx.currentTime);
      } catch (_) {}
    }

    if (this.audioEl) {
      this.audioEl.muted = this.muted;
      if (this.muted) {
        this.audioEl.pause();
      } else {
        this.audioEl.play().catch(() => {});
      }
    }

    this.onStateChange(this.muted ? 'muted' : 'active');
    return this.muted;
  }

  stop() {
    if (this.audioEl) {
      try {
        this.audioEl.pause();
        this.audioEl.currentTime = 0;
      } catch (_) {}
    }
  }

  destroy() {
    this.stop();
    try { this.ctx?.close(); } catch (_) {}
  }
}

// ────────────────────────────────────────────────────────────────────
// MAIN CLASS
// ────────────────────────────────────────────────────────────────────
export class SignatureIntro {
  constructor(threeEngine, onDismiss) {
    this.engine        = threeEngine;
    this.onDismiss     = onDismiss || (() => {});
    this.overlay       = null;
    this.svgEl         = null;
    this.letterEls     = [];
    this.flourishEl    = null;
    this.audio         = new PenAudio();
    this.complete      = false;
    this.dismissed     = false;
    this.tl            = null;
    this.reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    this._soundPill    = null;
    this._cleanupFns   = [];
  }

  // ── Public API ────────────────────────────────────────────────────

  async init() {
    this._buildDOM();
    this._lockScroll();

    await this.audio.setup((state) => this._updateSoundPill(state));

    const unlockHandler = async () => {
      if (this.audio.isBlocked) {
        await this.audio.unlock();
        if (this.tl && this.tl.isActive()) {
          const currentTime = this.tl.time();
          if (currentTime >= 0.60) {
            this.audio.playAt(currentTime);
          }
        }
      }
    };

    window.addEventListener('pointerdown', unlockHandler, { passive: true });
    window.addEventListener('touchstart',  unlockHandler, { passive: true });
    window.addEventListener('keydown',     unlockHandler, { passive: true });
    this._cleanupFns.push(
      () => window.removeEventListener('pointerdown', unlockHandler),
      () => window.removeEventListener('touchstart',  unlockHandler),
      () => window.removeEventListener('keydown',     unlockHandler),
    );

    if (this.reducedMotion) {
      this._showCompletedInstantly();
      return;
    }

    await new Promise(r => setTimeout(r, 60));
    this._initPathLengths();
    this._runAnimation();
  }

  // ── DOM Construction ──────────────────────────────────────────────

  _buildDOM() {
    this.overlay = el('div', {
      id:    'sig-intro',
      role:  'region',
      'aria-label': 'Portfolio introduction — Rohan Rakshe',
    });

    const grain = el('div', { id: 'sig-grain', 'aria-hidden': 'true' });
    this.overlay.appendChild(grain);

    const sigWrap = el('div', { id: 'sig-wrap', 'aria-hidden': 'true' });
    this.svgEl = this._buildSVG();
    sigWrap.appendChild(this.svgEl);
    this.overlay.appendChild(sigWrap);

    const sub = el('p', { id: 'sig-subtitle' }, 'Computer Science × Intelligent Systems');
    this.overlay.appendChild(sub);

    const prompt = el('div', { id: 'sig-prompt', 'aria-label': 'Scroll to enter portfolio' });
    const tick   = el('span', { class: 'sig-prompt-tick', 'aria-hidden': 'true' }, '↓');
    const ptxt   = el('span', { class: 'sig-prompt-text' }, 'Scroll to begin');
    prompt.appendChild(tick);
    prompt.appendChild(ptxt);

    this.overlay.appendChild(prompt);

    document.body.prepend(this.overlay);
  }

  _updateSoundPill(state) {
    if (!this._soundPill) return;
    const icon = this._soundPill.querySelector('.sig-sound-icon');
    const label = this._soundPill.querySelector('.sig-sound-label');
    if (state === 'blocked') {
      this._soundPill.className = 'sig-sound-pill blocked';
      if (icon) icon.textContent = '🔈';
      if (label) label.textContent = 'Tap for sound';
    } else if (state === 'muted') {
      this._soundPill.className = 'sig-sound-pill muted';
      if (icon) icon.textContent = '🔇';
      if (label) label.textContent = 'Sound Muted';
    } else {
      this._soundPill.className = 'sig-sound-pill';
      if (icon) icon.textContent = '🔊';
      if (label) label.textContent = 'Sound On';
    }
  }

  _buildSVG() {
    const svg = svgNS('svg');
    svg.setAttribute('id', 'sig-svg');
    svg.setAttribute('viewBox', `0 0 ${VB_W} ${VB_H}`);
    svg.setAttribute('preserveAspectRatio', 'xMidYMid meet');
    svg.setAttribute('aria-hidden', 'true');

    const defs = svgNS('defs');
    const filt = svgNS('filter');
    filt.setAttribute('id', 'sig-filt');
    filt.setAttribute('x', '-5%'); filt.setAttribute('y', '-5%');
    filt.setAttribute('width', '110%'); filt.setAttribute('height', '110%');
    const blur = svgNS('feTurbulence');
    blur.setAttribute('type', 'fractalNoise');
    blur.setAttribute('baseFrequency', '0.65');
    blur.setAttribute('numOctaves', '3');
    blur.setAttribute('stitchTiles', 'stitch');
    blur.setAttribute('result', 'noise');
    const disp = svgNS('feDisplacementMap');
    disp.setAttribute('in', 'SourceGraphic');
    disp.setAttribute('in2', 'noise');
    disp.setAttribute('scale', '1.8');
    disp.setAttribute('xChannelSelector', 'R');
    disp.setAttribute('yChannelSelector', 'G');
    filt.appendChild(blur);
    filt.appendChild(disp);
    defs.appendChild(filt);
    svg.appendChild(defs);

    const group = svgNS('g');
    group.setAttribute('filter', 'url(#sig-filt)');

    // Letter elements
    LETTERS.forEach((l, i) => {
      const p = svgNS('path');
      p.setAttribute('d', l.d);
      p.setAttribute('fill', 'rgba(200, 168, 130, 0)');
      p.setAttribute('stroke', '#C8A882');
      p.setAttribute('stroke-width', '2.2');
      p.setAttribute('stroke-linecap', 'round');
      p.setAttribute('stroke-linejoin', 'round');
      p.id = `sig-l${i}`;
      group.appendChild(p);
      this.letterEls.push(p);
    });

    // Flourish underline element
    this.flourishEl = svgNS('path');
    this.flourishEl.setAttribute('d', FLOURISH_PATH);
    this.flourishEl.setAttribute('fill', 'none');
    this.flourishEl.setAttribute('stroke', '#C8A882');
    this.flourishEl.setAttribute('stroke-width', '4.2');
    this.flourishEl.setAttribute('stroke-linecap', 'round');
    this.flourishEl.setAttribute('stroke-linejoin', 'round');
    this.flourishEl.id = 'sig-flourish';
    group.appendChild(this.flourishEl);

    svg.appendChild(group);
    return svg;
  }

  _initPathLengths() {
    this.letterEls.forEach((p) => {
      try {
        const len = p.getTotalLength();
        p.style.strokeDasharray  = len + 2;
        p.style.strokeDashoffset = len + 2;
        p.style.fill             = 'rgba(200, 168, 130, 0)';
      } catch (_) {
        p.style.strokeDasharray  = 600;
        p.style.strokeDashoffset = 600;
      }
    });

    if (this.flourishEl) {
      try {
        const fLen = this.flourishEl.getTotalLength();
        this.flourishEl.style.strokeDasharray  = fLen + 2;
        this.flourishEl.style.strokeDashoffset = fLen + 2;
      } catch (_) {
        this.flourishEl.style.strokeDasharray  = 800;
        this.flourishEl.style.strokeDashoffset = 800;
      }
    }
  }

  // ── Animation timeline: Quick Signature Writing ───────────────────

  _runAnimation() {
    this.complete = false;

    gsap.to(this.overlay, { opacity: 1, duration: 0.4, ease: 'power1.in' });

    this.tl = gsap.timeline({ paused: false });

    // 0.0–0.60s: Near silence on empty dark canvas
    this.tl.to({}, { duration: 0.60 });

    // At 0.60s: Play authentic pen audio (exact touchdown contact!)
    this.tl.call(() => {
      this.audio.playAt(0.60);
    }, null, 0.60);

    // Quick writing durations per letter (fast, confident handwriting rhythm):
    // "Rohan" (5 letters: indices 0..4)
    // Pen lift (180ms)
    // "Rakshe" (6 letters: indices 5..10)
    const letterDurs = [
      0.24, 0.15, 0.18, 0.16, 0.18, // R, o, h, a, n
      0.24, 0.15, 0.18, 0.14, 0.18, 0.16 // R, a, k, s, h, e
    ];

    let t = 0.60;

    for (let i = 0; i < this.letterEls.length; i++) {
      const el = this.letterEls[i];
      const dur = letterDurs[i] || 0.16;

      // Authentic pen lift & reposition between "Rohan" and "Rakshe"
      if (i === 5) {
        t += 0.18; // human pen lift
      }

      // Draw letter stroke
      this.tl.to(
        el,
        {
          strokeDashoffset: 0,
          duration: dur,
          ease: 'none',
        },
        t,
      );

      // Calligraphic ink fills in smoothly as pen sweeps across
      this.tl.to(
        el,
        {
          fill: 'rgba(200, 168, 130, 1)',
          duration: 0.10,
          ease: 'power1.in',
        },
        t + dur * 0.65,
      );

      // Cursive letters overlap slightly as the stroke glides into the next
      t += dur * 0.90;
    }

    // Deliberate pause before the decisive underline flourish (150ms)
    t += 0.15;

    // Swift, confident underline flourish sweep!
    this.tl.to(
      this.flourishEl,
      {
        strokeDashoffset: 0,
        duration: 0.45,
        ease: 'power2.out',
      },
      t,
    );

    const finishTime = t + 0.45;

    // Subtle warm shimmer on flourish completion
    this.tl.to(
      this.flourishEl,
      { attr: { stroke: '#D4A270' }, duration: 0.30, yoyo: true, repeat: 1 },
      finishTime,
    );

    // Intentional 0.4s pause of silence after completion
    this.tl.call(() => {
      this.complete = true;
    }, null, finishTime + 0.40);

    // Subtitle appears quietly
    this.tl.to(
      '#sig-subtitle',
      { opacity: 1, y: 0, duration: 0.65, ease: 'power2.out' },
      finishTime + 0.60,
    );

    // "Scroll to begin" & Replay appears
    this.tl.to(
      '#sig-prompt',
      { opacity: 1, duration: 0.55, ease: 'power1.out' },
      finishTime + 1.15,
    );

    this.tl.call(() => this._enableScrollListener(), null, finishTime + 1.25);
  }

  replay() {
    if (this.dismissed) return;
    this.audio.stop();
    this._initPathLengths();
    gsap.set('#sig-subtitle', { opacity: 0, y: 8 });
    gsap.set('#sig-prompt',   { opacity: 0 });
    if (this.tl) this.tl.kill();
    this._runAnimation();
  }

  _showCompletedInstantly() {
    gsap.set(this.overlay, { opacity: 1 });
    this.letterEls.forEach(p => {
      p.style.strokeDashoffset = 0;
      p.style.fill = 'rgba(200, 168, 130, 1)';
    });
    if (this.flourishEl) {
      this.flourishEl.style.strokeDashoffset = 0;
    }
    gsap.set('#sig-subtitle', { opacity: 1, y: 0 });
    gsap.set('#sig-prompt',   { opacity: 1 });
    this.complete = true;
    this._enableScrollListener();
  }

  // ── Scroll listener + transition ──────────────────────────────────

  _enableScrollListener() {
    const trigger = (e) => {
      if (!this.complete || this.dismissed) return;
      this.dismissed = true;

      if (e.cancelable) e.preventDefault();

      this._cleanupFns.forEach(fn => fn());
      this._runExitTransition();
    };

    const wheelFn    = (e) => trigger(e);
    const touchFn    = () => trigger({ cancelable: false });
    const keyFn      = (e) => { if (['ArrowDown','PageDown','Space',' '].includes(e.key)) trigger(e); };

    window.addEventListener('wheel',     wheelFn, { passive: false });
    window.addEventListener('touchmove', touchFn, { passive: true });
    window.addEventListener('keydown',   keyFn);

    this._cleanupFns.push(
      () => window.removeEventListener('wheel',     wheelFn),
      () => window.removeEventListener('touchmove', touchFn),
      () => window.removeEventListener('keydown',   keyFn),
    );
  }

  _runExitTransition() {
    this.audio.fadeOut(0.45);

    const tl = gsap.timeline({
      onComplete: () => this._completeExit(),
    });

    // Phase 1: UI fades
    tl.to(['#sig-subtitle', '#sig-prompt'], {
      opacity: 0, duration: 0.35, ease: 'power2.in',
    }, 0);

    // Phase 2: Letters morph & disintegrate
    this.letterEls.forEach((p, i) => {
      const delay = i * 0.04;
      tl.to(p, {
        opacity:           0,
        strokeDashoffset:  -30,
        duration:          0.35,
        ease:              'power2.in',
      }, 0.1 + delay);
    });

    if (this.flourishEl) {
      tl.to(this.flourishEl, {
        opacity:          0,
        strokeDashoffset: -50,
        duration:         0.40,
        ease:             'power2.in',
      }, 0.25);
    }

    // Phase 3: Canvas particle burst bridges SVG → 3D
    tl.call(() => this._spawnParticles(), null, 0.20);

    // Phase 4: Overlay fades to reveal Three.js scene
    tl.to(this.overlay, {
      opacity:   0,
      duration:  0.70,
      ease:      'power2.inOut',
    }, 0.45);
  }

  _spawnParticles() {
    const svgRect = this.svgEl.getBoundingClientRect();
    const points = [];

    const sampleElements = [...this.letterEls];
    if (this.flourishEl) sampleElements.push(this.flourishEl);

    sampleElements.forEach(p => {
      try {
        const len = p.getTotalLength();
        const steps = Math.max(4, Math.floor(len / 32));
        for (let i = 0; i <= steps; i++) {
          const svgPt = p.getPointAtLength((i / steps) * len);
          const sx = svgRect.left + (svgPt.x / VB_W) * svgRect.width;
          const sy = svgRect.top  + (svgPt.y / VB_H) * svgRect.height;
          points.push({ x: sx, y: sy });
        }
      } catch (_) {}
    });

    if (!points.length) return;

    const canvas = el('canvas', {
      id:    'sig-particle-canvas',
      style: 'position:fixed;inset:0;width:100vw;height:100vh;z-index:10001;pointer-events:none;',
    });
    canvas.width  = window.innerWidth;
    canvas.height = window.innerHeight;
    document.body.appendChild(canvas);

    const ctx = canvas.getContext('2d');

    const particles = points.map(pt => ({
      x:    pt.x,
      y:    pt.y,
      vx:   (Math.random() - 0.5) * 5.5,
      vy:   (Math.random() - 0.6) * 5.5,
      size: Math.random() * 1.8 + 0.4,
      life: 1.0,
      decay: 0.018 + Math.random() * 0.014,
    }));

    const draw = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      let alive = false;
      particles.forEach(p => {
        if (p.life <= 0) return;
        alive = true;
        p.x   += p.vx;
        p.y   += p.vy;
        p.vy  += 0.06;
        p.life -= p.decay;

        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(200,168,130,${Math.max(0, p.life)})`;
        ctx.fill();
      });
      if (alive) requestAnimationFrame(draw);
      else canvas.remove();
    };

    requestAnimationFrame(draw);
  }

  _completeExit() {
    this.audio.destroy();
    this._unlockScroll();

    this.overlay?.remove();
    document.getElementById('sig-particle-canvas')?.remove();

    this.onDismiss();
  }

  _lockScroll() {
    document.documentElement.style.overflow = 'hidden';
    document.body.style.overflow            = 'hidden';
  }

  _unlockScroll() {
    document.documentElement.style.overflow = '';
    document.body.style.overflow            = '';
  }
}

export function initSignatureIntro(threeEngine) {
  return new Promise(resolve => {
    const intro = new SignatureIntro(threeEngine, resolve);
    intro.init();
  });
}
